const getSolaxyPrice = async ()=>{
    try {
        // Try CoinGecko first (free API)
        const coingeckoResponse = await fetch("https://api.coingecko.com/api/v3/simple/price?ids=solaxy&vs_currencies=usd&include_24hr_change=true&include_24hr_vol=true", {
            method: "GET",
            headers: {
                "Accept": "application/json"
            }
        });
        if (coingeckoResponse.ok) {
            const data = await coingeckoResponse.json();
            console.log("[SOLAXY_PRICE_DEBUG] CoinGecko response:", JSON.stringify(data, null, 2));
            if (data.solaxy) {
                const solaxyData = data.solaxy;
                const transformedData = {
                    firstPrice: solaxyData.usd?.toString() || "0",
                    high: solaxyData.usd?.toString() || "0",
                    lastPrice: solaxyData.usd?.toString() || "0",
                    low: solaxyData.usd?.toString() || "0",
                    priceChange: "0",
                    priceChangePercent: solaxyData.usd_24h_change?.toString() || "0",
                    quoteVolume: solaxyData.usd_24h_vol?.toString() || "0",
                    symbol: "SOLX_USD",
                    trades: "0",
                    volume: solaxyData.usd_24h_vol?.toString() || "0"
                };
                window.localStorage.setItem("solaxyPrice", JSON.stringify(transformedData));
                console.log("[SOLAXY_PRICE_DEBUG] Final transformed data:", JSON.stringify(transformedData, null, 2));
                return transformedData;
            }
        }
        // If CoinGecko doesn't have Solaxy, try alternative approach
        // Check if token exists on Solana blockchain and get price from DEX
        const solanaResponse = await fetch("https://api.dexscreener.com/latest/dex/tokens/0xe0B701F1a9c9D68B5C4c4c3B7FA4Ddec0fCF48", {
            method: "GET",
            headers: {
                "Accept": "application/json"
            }
        });
        if (solanaResponse.ok) {
            const dexData = await solanaResponse.json();
            console.log("[SOLAXY_PRICE_DEBUG] DEXScreener response:", JSON.stringify(dexData, null, 2));
            if (dexData.pairs && dexData.pairs.length > 0) {
                const pair = dexData.pairs[0];
                const transformedData = {
                    firstPrice: pair.priceUsd || "0",
                    high: pair.priceUsd || "0",
                    lastPrice: pair.priceUsd || "0",
                    low: pair.priceUsd || "0",
                    priceChange: pair.priceChange24h || "0",
                    priceChangePercent: pair.priceChange24h || "0",
                    quoteVolume: pair.volume24h || "0",
                    symbol: "SOLX_USD",
                    trades: "0",
                    volume: pair.volume24h || "0"
                };
                window.localStorage.setItem("solaxyPrice", JSON.stringify(transformedData));
                console.log("[SOLAXY_PRICE_DEBUG] Final DEX data:", JSON.stringify(transformedData, null, 2));
                return transformedData;
            }
        }
        // If all APIs fail, throw error
        throw new Error("No API returned Solaxy data");
    } catch (error) {
        console.error("[SOLAXY_PRICE_DEBUG] Error fetching Solaxy price:", error);
        // Only fallback to cached data if available
        const cachedData = window.localStorage.getItem("solaxyPrice");
        if (cachedData) {
            try {
                const parsedCache = JSON.parse(cachedData);
                console.log("[SOLAXY_PRICE_DEBUG] Using cached data:", JSON.stringify(parsedCache, null, 2));
                return parsedCache;
            } catch (parseError) {
                console.error("Error parsing cached data:", parseError);
            }
        }
        // No fallback data - throw error
        throw new Error("Failed to fetch Solaxy price from all sources and no cached data available");
    }
};
